// HasWorkspace applies the HasEdge predicate on the "workspace" edge.
func HasWorkspace() predicate.OutboundMessage {
	return predicate.OutboundMessage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkspaceTable, WorkspaceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkspaceWith applies the HasEdge predicate on the "workspace" edge with a given conditions (other predicates).
func HasWorkspaceWith(preds ...predicate.Workspace) predicate.OutboundMessage {
	return predicate.OutboundMessage(func(s *sql.Selector) {
		step := newWorkspaceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OutboundMessage) predicate.OutboundMessage {
	return predicate.OutboundMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OutboundMessage) predicate.OutboundMessage {
	return predicate.OutboundMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OutboundMessage) predicate.OutboundMessage {
	return predicate.OutboundMessage(sql.NotPredicates(p))
}
